-- SOURCE: 20261005100000_traffic_service_book.sql (sto_read_object_v1 only)
create or replace function public.sto_read_object_v1(p_value jsonb)
returns jsonb language plpgsql immutable security invoker
set search_path = pg_catalog
as $$
declare parsed jsonb;
begin
  if jsonb_typeof(p_value) = 'object' then return p_value; end if;
  if jsonb_typeof(p_value) = 'string' then
    begin
      parsed := (p_value #>> '{}')::jsonb;
      if jsonb_typeof(parsed) = 'object' then return parsed; end if;
    exception when invalid_text_representation then return '{}'::jsonb;
    end;
  end if;
  return '{}'::jsonb;
end;
$$;
revoke all on function public.sto_read_object_v1(jsonb) from public;
grant execute on function public.sto_read_object_v1(jsonb) to anon, authenticated;

-- SOURCE: 20261011080000_traffic_payroll_json.sql (payroll_json_object only)
create or replace function public.payroll_json_object(p_value jsonb)
returns jsonb language plpgsql immutable security invoker set search_path=pg_catalog as $$
begin
 if jsonb_typeof(p_value)='string' then p_value:=(p_value#>>'{}')::jsonb;end if;
 if jsonb_typeof(p_value) is distinct from 'object' then raise exception 'Некоректні дані зарплати' using errcode='40001';end if;
 return p_value;
end $$;
revoke all on function public.payroll_json_object(jsonb) from public;
grant execute on function public.payroll_json_object(jsonb) to anon, authenticated;

-- SOURCE: 20261013120709_traffic_profit_date_compatibility.sql (traffic_profit_acts only)
create or replace function public.traffic_profit_acts(
 p_mode text, p_from text, p_to text default null, p_offset integer default 0
) returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare
 result jsonb;
 date_column text;
 date_type text;
begin
 if p_mode not in ('open','close','paid') or p_mode is null then raise exception 'Invalid date mode'; end if;
 if p_offset is null or p_offset<0 then raise exception 'Invalid offset'; end if;
 -- Cast parameters to the actual column type, never the indexed column.
 -- Older projects use text; newer templates use timestamp for rosraxovano.
 date_column := case p_mode when 'open' then 'date_on' when 'close' then 'date_off' else 'rosraxovano' end;
 select case a.atttypid
   when 'timestamp'::regtype then 'timestamp'
   when 'timestamptz'::regtype then 'timestamptz'
   when 'date'::regtype then 'date'
   when 'text'::regtype then 'text'
   when 'varchar'::regtype then 'text'
 end into date_type
 from pg_attribute a
 where a.attrelid='public.acts'::regclass and a.attname=date_column
   and a.attnum>0 and not a.attisdropped;
 if date_type is null then
   raise exception 'Unsupported or missing date column public.acts.%', date_column;
 end if;
 execute format($query$
 with candidates as (
   select a.act_id,a.date_on,to_jsonb(a) row_data,public.sto_read_object_v1(to_jsonb(a.data)) body
   from public.acts a
   where ($1 is null or a.%1$I >= $1::%2$s)
     and ($2 is null or a.%1$I <= $2::%2$s)
   order by a.date_on desc,a.act_id desc limit 201 offset $3
 ), page as (select * from candidates order by date_on desc,act_id desc limit 200)
 select jsonb_build_object('items',coalesce((select jsonb_agg(
   (select jsonb_object_agg(key,value) from jsonb_each(p.row_data)
    where key=any(array['act_id','date_on','date_off','rosraxovano','xto_rozraxuvav','client_id','cars_id','avans','tupOplatu']))
   ||jsonb_build_object('data',(select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) from jsonb_each(p.body)
    where key=any(array['Прибуток за деталі','Прибуток за роботу','За деталі','За роботу','Знижка','Заморожений'])))
   order by p.date_on desc,p.act_id desc) from page p),'[]'::jsonb),
   'has_more',(select count(*)>200 from candidates))
 $query$, date_column, date_type) into result using p_from, p_to, p_offset;
 return result;
end $$;
revoke all on function public.traffic_profit_acts(text,text,text,integer) from public;
grant execute on function public.traffic_profit_acts(text,text,text,integer) to anon, authenticated;

-- SOURCE: 20261010010000_traffic_receipter_salaries.sql (traffic_receipter_salaries only)
create or replace function public.traffic_receipter_salaries(p_ids bigint[])
returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare result jsonb;
begin
 if coalesce(cardinality(p_ids),0)>200 then raise exception 'At most 200 act IDs'; end if;
 if coalesce(cardinality(p_ids),0)=0 then return '[]'::jsonb; end if;
 with staff as (select slyusar_id,public.sto_read_object_v1(to_jsonb(data)) d from public.slyusars),
 entries as (
 select s.slyusar_id,day.key,entry.ordinality,entry.value r
 from staff s cross join lateral jsonb_each(case when jsonb_typeof(s.d->'Історія')='object' then s.d->'Історія' else '{}'::jsonb end) day
 cross join lateral jsonb_array_elements(case when jsonb_typeof(day.value)='array' then day.value else '[]'::jsonb end) with ordinality entry
 where s.d->>'Доступ'='Приймальник'
 )
 select coalesce(jsonb_agg(jsonb_build_object('Акт',r->'Акт','ЗарплатаЗапчастин',r->'ЗарплатаЗапчастин',
 'ЗарплатаРоботи',r->'ЗарплатаРоботи','ЗарплатаЗапчастистів',r->'ЗарплатаЗапчастистів') order by slyusar_id,key,ordinality),'[]'::jsonb)
 into result from entries where
 case when length(coalesce(r->>'Акт',''))<40 and r->>'Акт' ~ '^\s*[+]?[0-9]+(\.0+)?\s*$'
 then (r->>'Акт')::numeric=any(p_ids::numeric[]) else true end;
 -- Unusual legacy ID strings remain for exact JavaScript Number matching by caller.
 return result;
end $$;
revoke all on function public.traffic_receipter_salaries(bigint[]) from public;
grant execute on function public.traffic_receipter_salaries(bigint[]) to anon, authenticated;

-- SOURCE: 20261012122102_accounting_traffic_optimization.sql (traffic_profit_labels only)
create or replace function public.traffic_profit_labels(p_resource text,p_ids bigint[])
returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare result jsonb;
begin
 if coalesce(cardinality(p_ids),0)>200 then raise exception 'Завеликий пакет підписів';end if;
 if p_resource='clients' then
  select coalesce(jsonb_agg(jsonb_build_object('id',client_id,'data',jsonb_build_object('ПІБ',d->'ПІБ','Телефон',d->'Телефон','Джерело',d->'Джерело','Додаткові',d->'Додаткові'))),'[]') into result
  from (select client_id,public.payroll_json_object(to_jsonb(data)) d from public.clients where client_id=any(p_ids)) q;
 elsif p_resource='cars' then
  select coalesce(jsonb_agg(jsonb_build_object('id',cars_id,'data',jsonb_build_object('Авто',d->'Авто','Номер авто',d->'Номер авто','Обʼєм',d->'Обʼєм','КодДВЗ',d->'КодДВЗ','Пальне',d->'Пальне'))),'[]') into result
  from (select cars_id,public.payroll_json_object(to_jsonb(data)) d from public.cars where cars_id=any(p_ids)) q;
 else raise exception 'Невідомий довідник';end if;
 return result;
end $$;
revoke all on function public.traffic_profit_labels(text,bigint[]) from public;
grant execute on function public.traffic_profit_labels(text,bigint[]) to anon, authenticated;

notify pgrst, 'reload schema';
